widget.solution:
def descend_1d(fprime, x0, s, n):
    x = x0
    for _ in range(n):
        x = x - s * fprime(x)
    return x


def basins(fprime, starts, s, n):
    return [round(descend_1d(fprime, x0, s, n), 6) for x0 in starts]
